"""Generate the continuity-fix report from the existing manifest and measured QA."""
import html
import json
import pathlib

project = pathlib.Path(__file__).resolve().parents[1]
out = project / 'artifacts/cinematic-continuity'
manifest = json.loads((project / 'public/images/cinematic hero section/manifest.json').read_text())
qa = json.loads((out / 'browser-validation.json').read_text())
extended = json.loads((out / 'extended-validation.json').read_text())
if (out / 'visibility-validation.json').exists():
    extended['scenarios']['simulatedVisibility'] = json.loads((out / 'visibility-validation.json').read_text())
rows, motion, videos = [], [], []
for name, seq in manifest['sequences'].items():
    metrics = qa['variants'][name]
    slow = metrics['slowMotion']
    rows.append(f"<tr><th>{name}</th><td>{seq['frameCount']:,}</td><td>{seq['width']} × {seq['height']}</td><td>{seq['fps']}</td><td>{seq['totalBytes']:,} bytes / {seq['totalBytes']/1e6:.2f} MB</td><td>{seq['averageFrameBytes']/1000:.2f} KB</td></tr>")
    motion.append(f"<li><strong>{name}</strong>: {slow['uniqueDisplayedFrames']} distinct displayed frames in the six-second slow-scroll phase; {slow['exactSampleFraction']:.2%} of {slow['ticks']} sampled ticks matched target; {slow['delayedAnimationTicks']} ticks exceeded 25ms. Maximum sampled index lag {slow['maxFrameLag']} includes the initial jump into the phase. Entire demonstration: {metrics['drawCount']} draws, p95 synchronous draw call {metrics['drawP95Milliseconds']:.2f}ms, {metrics['longTaskCount']} long tasks (max {metrics['longestTaskMilliseconds']:.0f}ms). Initial resource transfer {metrics['initialTransferBytes']:,} bytes; traversal resource transfer {metrics['traversalTransferBytes']:,} bytes. Request count {metrics['requests']} includes cancellations/revisits.</li>")
    videos.append(f'<article><h3>{name.title()}</h3><video controls preload="metadata" src="{name}-scroll-recording.webm"></video><p><a href="{name}-scroll-recording.webm">Open recording</a></p><img src="{name}-canvas-hero.png" alt="{name} Canvas homepage"></article>')
times = [0, 3.2, 7, 19.5, 34.5, 41.5, 49.5, 54, manifest['duration']]
labels = ['Hero: exterior / entrance', 'Marquee: entrance walkway', 'Promotions: dining room', 'Menu: kitchen / preparation', 'Reservation: dining tables', 'Reviews: guests dining', 'Contact: reception / closing', 'Footer: final reception frames']
mapping = []
for i, label in enumerate(labels):
    ranges = []
    for name in ['desktop', 'mobile']:
        seq = manifest['sequences'][name]
        frames = [min(seq['endIndex'], int(t * seq['fps']) + 1) for t in times[i:i+2]]
        ranges.append(f'<td>{frames[0]} → {frames[1]}</td>')
    mapping.append(f'<tr><th>{label}</th><td>{times[i]:g} → {times[i+1]:g}s</td>{"".join(ranges)}</tr>')
engine_rows = ''.join(f'<li>{html.escape(name)}: {html.escape(json.dumps(value))}</li>' for name, value in extended['engines'].items())
scenarios = ''.join(f'<li><strong>{html.escape(key)}</strong>: {html.escape(value if isinstance(value, str) else json.dumps(value))}</li>' for key, value in extended['scenarios'].items())
text = f'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>RESTRO — Cinematic continuity fix</title>
<style>body{{margin:0;background:#100e0b;color:#f0e9dd;font:16px/1.65 system-ui,sans-serif}}main{{max-width:1150px;margin:auto;padding:40px 24px}}h1,h2,h3{{font-family:Georgia,serif;font-weight:400;line-height:1.2}}h1{{font-size:clamp(32px,5vw,56px)}}h2{{margin-top:42px;color:#d8b37a}}a{{color:#d8b37a}}table{{border-collapse:collapse;width:100%;font-size:14px}}td,th{{text-align:left;padding:12px;border-bottom:1px solid #ffffff24}}.table{{overflow:auto}}.media{{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:24px}}video,img{{width:100%;height:auto;max-height:750px;object-fit:contain;background:#090807}}code{{overflow-wrap:anywhere}}.muted{{color:#bcb4a6}}</style>
<main><p class="muted">25 November 2026 · Verified production preview: <a href="http://localhost:3200">localhost:3200</a></p><h1>RESTRO cinematic continuity</h1>
<h2>Root cause and correction</h2><p>The source already had a Canvas renderer. At task start port 3200 served Canvas markup but returned HTTP404 for the frame manifest; port 3100 served the older video build and also lacked the manifest. Port 3201 could load the frames. A missing manifest activated permanent fallback and the previous fallback logic switched among seven representative scene images. This explains a concrete route to the reported slideshow; the user's exact prior browser preference/URL was not inspected.</p>
<p>All three processes were identified by their repository-specific Next start command lines, stopped, and replaced with the current production preview at port 3200. No asset regeneration was needed. The exact-only drawing path also held unnecessarily during short cache misses, lacked a decoder alternative and did not communicate fallback reasons. These paths are now corrected. There is no section-based background-image switching; the initial poster and frozen Canvas are the only static surfaces.</p>
<h2>Existing frame inventory</h2><div class="table"><table><tr><th>Sequence</th><th>Frames</th><th>Dimensions</th><th>FPS</th><th>Size</th><th>Average</th></tr>{''.join(rows)}</table></div>
<p>Combined sequence storage: {manifest['totalBytes']:,} bytes / {manifest['totalBytes']/1e6:.2f} MB. Existing libwebp desktop q80/mobile q75, compression level 6, lossy, 16:9 frames and directory names unchanged. Full picture duration {manifest['duration']} seconds. No frames were regenerated or relocated.</p>
<h2>Continuous section mapping</h2><p>Reviewed actual sequence frames at all editorial anchors. The table lists shared interpolation endpoints, not screenshot replacements or detected hard cuts. At 25s, the menu passage reaches preparation/plating (desktop 751, mobile 601). Actual section positions are measured; tall mobile sections receive their own scene ranges rather than stretching the whole film uniformly.</p><div class="table"><table><tr><th>Content / observed footage</th><th>Time range</th><th>Desktop index</th><th>Mobile index</th></tr>{''.join(mapping)}</table></div><img src="timeline.jpg" alt="Actual sequence images at the editorial scene anchors">
<h2>Architecture, loading and memory</h2><ul><li>One fixed, pointer-inert, aria-hidden Canvas below the contrast overlay, architectural grid and existing content. Native touch/wheel scroll remains untouched. Scroll and decode events schedule one centralized rAF controller; no per-frame React state or idle animation loop.</li><li>The latest target is authoritative. Exact frames render first; a nearby decoded image within 12 frames may bridge a miss only if it lies chronologically between the previous display and target. Obsolete results cannot draw directly. The last complete Canvas stays visible during larger misses. Stopping settles at the exact available target.</li><li>Desktop: 4 requests, 36-frame directional compressed lookahead plus 6 behind; mobile: 3 requests, 20 ahead plus 6 behind. Request deduplication, latest-direction priority, stale aborts and two attempts for real failures. Compressed caches cap at 64 desktop / 40 mobile images; no full-sequence preload.</li><li>Decoded caches cap at 18 desktop frames (63.3 MiB RGBA) and 12 mobile (23.7 MiB). At most two decodes add about 7.0/4.0 MiB. Source-aware Canvas buffers and compressed blobs add overhead. Reported runtime estimates include cached/in-flight decoded pixels and Canvas, while actual browser/GPU copies may cost more. Evictions close bitmaps; inactive routes dispose caches and fetches.</li><li>createImageBitmap is preferred with a Blob-backed HTMLImageElement alternative. Repeated failures with no usable local frames activate a stable static fallback with a reason and retry control. Manifest failures retry once. Saved explicit preferences, reduced motion and Save-Data remain respected; capable mobile browsers animate by default.</li><li>Variant changes preserve the current timestamp, release the previous cache, map through the new FPS and hold the existing Canvas until replacement is ready. A continuity anchor survives repeated ResizeObserver measurements. Endpoints remain frame 1 and the actual final frame.</li><li>Cover drawing never stretches source pixels. Backing buffers cap DPR and source width. A gradual kitchen focal envelope replaces abrupt mobile section-boundary shifts. Keyboard/dialog editing holds camera position; hidden tabs pause requests and rendering. Geometry is cached and refreshed for layout/fonts/viewport/route events.</li></ul>
<h2>Measured performance</h2><ul>{''.join(motion)}</ul><p>Transfer counts use Resource Timing and exclude initial HTML and aborted requests. The full-sequence byte size is storage, not initial download. Slow-scroll index sampling is distinct from compositor FPS. Draw-call timings are synchronous CPU submissions, not GPU completion. The recordings include scripted slow and fast movement, direction changes, freezes, section interiors and crossings, plus native wheel/touch smoke tests. No guaranteed 60 FPS claim is made.</p>
<h2>Responsive, failure and regression results</h2><p>All nine widths passed: {', '.join(str(item['width']) for item in extended['responsive'])}px. Tested the hero, menu, reservation, reviews, contact and footer with actual Canvas pixels and no document overflow. The debug panel was verified in development against changing image pixels and displayed indexes; production contains no debug panel.</p><ul>{engine_rows}{scenarios}</ul>
<p>All existing project checks passed: cinematic mapping, frame loader, menu catalog (nine routes/48 products), offers, reservation/time picker, reviews/storage, enquiry/contact, mascot timeline and responsive arrows. The cart was already intentionally absent before this task; it was not recreated. TypeScript, zero-warning ESLint and the production build (16 expected routes/paths) passed. Existing UI components and data are unchanged.</p>
<h2>Recordings</h2><div class="media">{''.join(videos)}</div><h2>Development diagnostics</h2><img src="development-debug.png" alt="Development-only panel showing the actual frame cache and displayed frame"><p><a href="browser-validation.json">Traversal metrics</a> · <a href="extended-validation.json">Extended checks</a> · <a href="development-debug.json">Pixel/debug evidence</a></p>
<h2>Limitations and next steps</h2><p>All mobile tests are desktop emulation, not physical Android/iOS. Playwright WebKit is not a physical Safari device. Local browser tests do not establish production-host caching, low-memory device behavior, sustained GPU usage or WAN smoothness. Simulated delay and missing-image tests verify stability; low bandwidth or rapid jumps can still hold the previous picture. The header blur comparison is sequential local rAF timing, affected by cache/CPU scheduling, and does not isolate compositor/GPU cost. Headless visibility testing is reported with its actual hidden-state result. Independent image sequences remain larger than inter-frame compressed video. No backend, authentication, ordering, payment, new runtime package, deployment or source-video change was made.</p></main></html>'''
(out / 'report.html').write_text(text, encoding='utf-8')
print(out / 'report.html')
